"""Reference only, NOT a baseline (not in config.json): the task's former starter.

GPT-2's own block (nanoGPT): pre-LayerNorm, exact causal softmax attention
(scaled_dot_product_attention), pre-LayerNorm, GELU MLP 4x, GPT-2 init (N(0, 0.02), c_proj
scaled by 1/sqrt(2 n_layer)).  Kept so the subquadratic check can be shown to reject it; it is
quadratic in sequence length.

Fixed by the task (not part of the arm): the GPT-2 BPE token embedding (tied to the LM
head), the final norm (LayerNorm, no bias) + LM head, the training loop and the data.

Replaces the editable sequence-mixing stack (template lines 34-109) as one op.
"""

_FILE = "nanoGPT/custom_pretrain.py"

_STACK = '''\
USE_POS_EMB = True


class CausalSelfAttention(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.c_attn = nn.Linear(config.n_embd, 3 * config.n_embd, bias=config.bias)
        self.c_proj = nn.Linear(config.n_embd, config.n_embd, bias=config.bias)
        self.n_head = config.n_head
        self.n_embd = config.n_embd

    def forward(self, x):
        B, T, C = x.size()
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        q, k, v = [t.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) for t in (q, k, v)]
        y = F.scaled_dot_product_attention(q, k, v, is_causal=True)
        return self.c_proj(y.transpose(1, 2).contiguous().view(B, T, C))


class MLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.c_fc = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_proj = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)

    def forward(self, x):
        return self.c_proj(F.gelu(self.c_fc(x)))


class Block(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp = MLP(config)

    def forward(self, x, layer_idx=0, ctx=None):
        x = x + self.attn(self.ln_1(x))
        return x + self.mlp(self.ln_2(x))


def build_layers(config):
    layers = nn.ModuleList([Block(config) for _ in range(config.n_layer)])
    for name, p in layers.named_parameters():
        if p.dim() >= 2:
            nn.init.normal_(p, mean=0.0, std=0.02)
            if name.endswith("c_proj.weight"):
                with torch.no_grad():
                    p.div_(math.sqrt(2 * config.n_layer))
    return layers
'''

OPS = [
    {"op": "replace", "file": _FILE, "start_line": 34, "end_line": 109, "content": _STACK},
]

